<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import client from '../api/client'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'
const router=useRouter(),data=ref<any>({states:{},latest_monitors:[],recent_incidents:[],probe_stats_24h:{}}),error=ref(''),loading=ref(false),refreshSeconds=ref(30),lastUpdated=ref(''),live=ref(false)
let timer:number|undefined,socket:WebSocket|undefined,reconnectTimer:number|undefined,reloadTimer:number|undefined,stopped=false,requestVersion=0
const stateText:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',MAINTENANCE:'维护',PAUSED:'暂停',PENDING:'待探测',UNKNOWN:'未知'}
const stateClass=(s:string)=>s?.toLowerCase()||'unknown'
const totalStates=computed(()=>Object.values(data.value.states||{}).reduce((a:number,b:any)=>a+Number(b),0))
const healthyRate=computed(()=>data.value.health_rate==null?0:Number(data.value.health_rate))
const businessRows=computed(()=>{const map:any={};for(const m of data.value.latest_monitors||[]){const item=map[m.business]||(map[m.business]={name:m.business,total:0,up:0,down:0,degraded:0,pending:0,maintenance:0,last:null});item.total++;if(m.status==='UP')item.up++;if(m.status==='DOWN')item.down++;if(m.status==='DEGRADED')item.degraded++;if(['PENDING','UNKNOWN'].includes(m.status))item.pending++;if(m.status==='MAINTENANCE')item.maintenance++;if(!item.last||m.last_checked_at>item.last)item.last=m.last_checked_at}return (Object.values(map) as any[]).sort((a:any,b:any)=>(b.down+b.degraded)-(a.down+a.degraded))})
const attention=computed(()=>(data.value.latest_monitors||[]).filter((m:any)=>m.available===false||['DOWN','DEGRADED','PENDING'].includes(m.status)).slice(0,8))
const fmt=(v:any)=>v?new Date(v).toLocaleString():'—'
async function load(){if(stopped)return;const version=++requestVersion;loading.value=true;try{const response=await client.get('/dashboard/summary/');if(stopped||version!==requestVersion)return;data.value=response.data;lastUpdated.value=new Date(response.data.snapshot_at||Date.now()).toLocaleTimeString();error.value=''}catch(e:any){if(!stopped&&version===requestVersion)error.value=e.response?.data?.message||e.message||'总览加载失败'}finally{if(version===requestVersion)loading.value=false}}
function scheduleLoad(){if(stopped||reloadTimer)return;reloadTimer=window.setTimeout(()=>{reloadTimer=undefined;load()},300)}
function resetTimer(){if(timer)clearInterval(timer);if(refreshSeconds.value)timer=window.setInterval(load,refreshSeconds.value*1000)}
function connect(){const token=localStorage.getItem('access_token');if(!token||stopped)return;const protocol=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${protocol}://${location.host}/ws/v1/status/?token=${encodeURIComponent(token)}`);socket.onopen=()=>live.value=true;socket.onclose=()=>{live.value=false;if(!stopped)reconnectTimer=window.setTimeout(connect,5000)};socket.onmessage=e=>{try{if(['monitor.result','monitor.status'].includes(JSON.parse(e.data).type))scheduleLoad()}catch{live.value=false}}}
watch(refreshSeconds,resetTimer);onMounted(async()=>{stopped=false;load();connect();try{await loadSystemSettings();refreshSeconds.value=systemSettings.dashboard_refresh_seconds}catch{refreshSeconds.value=30}if(!stopped)resetTimer()});onBeforeUnmount(()=>{stopped=true;requestVersion++;if(reloadTimer)clearTimeout(reloadTimer);if(timer)clearInterval(timer);if(reconnectTimer)clearTimeout(reconnectTimer);socket?.close()})
</script>
<template>
<div class="heading"><div><h2>监控总览</h2><p>业务可用性与当前故障态势 · 更新于 {{lastUpdated||'—'}}</p></div><div class="actions"><span class="live-pill" :class="{online:live}"><i/>{{live?'实时数据已连接':'定时刷新模式'}}</span><el-select v-model="refreshSeconds" style="width:112px"><el-option label="10 秒" :value="10"/><el-option label="30 秒" :value="30"/><el-option label="1 分钟" :value="60"/><el-option label="关闭" :value="0"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div></div>
<el-alert v-if="error" :title="error" type="error" show-icon class="error"/>
<div class="hero-grid" v-loading="loading&&!lastUpdated" :aria-busy="loading&&!lastUpdated"><section class="health-card"><div><span>整体健康度</span><strong>{{data.health_rate==null?'—':healthyRate}}<em v-if="data.health_rate!=null">%</em></strong><p>{{data.states?.UP||0}} 个正常，共 {{totalStates}} 个监控项</p></div><div class="ring" :style="{'--rate':healthyRate+'%'}"><b>{{data.health_rate==null?'暂无评估':(data.states?.DOWN||data.states?.DEGRADED)?'需关注':data.states?.PENDING||data.states?.UNKNOWN?'待确认':'健康'}}</b></div></section><section class="metric-card"><span>业务系统</span><strong>{{data.businesses_total||0}}</strong><p>纳入可用性监控</p></section><section class="metric-card"><span>监控任务</span><strong>{{data.monitors_total||0}}</strong><p>24h 探测 {{data.probe_stats_24h?.total||0}} 次</p></section><section class="metric-card good"><span>24h 成功率</span><strong>{{data.probe_stats_24h?.success_rate==null?'—':data.probe_stats_24h.success_rate+'%'}}</strong><p>成功 {{data.probe_stats_24h?.passed||0}} 次</p></section><section class="metric-card danger"><span>开放事件</span><strong>{{data.open_incidents||0}}</strong><p>今日新增 {{data.today_incidents||0}} 个</p></section></div>
<div class="content-grid"><el-card shadow="never"><template #header><div class="card-title"><div><b>监控状态分布</b><span>当前所有任务的最新状态</span></div><el-button link type="primary" @click="router.push('/monitors')">管理任务</el-button></div></template><div class="state-list"><div v-for="s in ['UP','DOWN','DEGRADED','MAINTENANCE','PAUSED','PENDING','UNKNOWN']" :key="s" class="state-row"><span><i :class="stateClass(s)"/>{{stateText[s]}}</span><b>{{data.states?.[s]||0}}</b><div><em :class="stateClass(s)" :style="{width:(totalStates?(data.states?.[s]||0)/totalStates*100:0)+'%'}"/></div></div></div></el-card><el-card shadow="never"><template #header><div class="card-title"><div><b>业务健康概览</b><span>按业务系统汇总监控状态</span></div><el-button link type="primary" @click="router.push('/businesses')">查看业务</el-button></div></template><div class="business-list"><div v-for="b in businessRows.slice(0,6)" :key="b.name" class="business-row"><div><b>{{b.name}}</b><span>{{b.total}} 个监控项 · {{fmt(b.last)}}</span></div><span class="business-status" :class="b.down?'down':b.degraded?'degraded':b.pending||!b.up?'pending':'up'">{{b.down?`${b.down} 个故障`:b.degraded?`${b.degraded} 个降级`:b.pending?'待确认':b.up?'运行正常':b.maintenance?'维护中':'暂无运行任务'}}</span></div><el-empty v-if="!businessRows.length" description="暂无业务数据" :image-size="60"/></div></el-card></div>
<el-card shadow="never" class="monitor-panel"><template #header><div class="card-title"><div><b>{{attention.length?'需要关注':'实时监控状态'}}</b><span>{{attention.length?'优先显示异常和待确认的探测任务':'当前全部探测均处于正常状态'}}</span></div><el-button link type="primary" @click="router.push('/monitor-results')">查看探测结果</el-button></div></template><el-table :data="attention.length?attention:data.latest_monitors" stripe empty-text="暂无监控任务"><el-table-column prop="business" label="业务系统" min-width="160"/><el-table-column prop="name" label="探测任务" min-width="180"/><el-table-column prop="type" label="类型" width="90"/><el-table-column label="状态" width="110"><template #default="s"><span class="state-badge" :class="stateClass(s.row.status)"><i/>{{stateText[s.row.status]||s.row.status}}</span></template></el-table-column><el-table-column label="响应时间" width="125"><template #default="s">{{s.row.latency_ms==null?'—':s.row.latency_ms+' ms'}}</template></el-table-column><el-table-column label="最近探测" width="185"><template #default="s">{{fmt(s.row.last_checked_at)}}</template></el-table-column></el-table></el-card>
<el-card v-if="data.recent_incidents?.length" shadow="never" class="incident-panel"><template #header><div class="card-title"><div><b>未关闭事件</b><span>最近发生的业务故障事件</span></div><el-button link type="primary" @click="router.push('/incidents')">查看全部事件</el-button></div></template><div class="incident-list"><div v-for="i in data.recent_incidents" :key="i.id" class="incident"><span class="severity" :class="i.severity.toLowerCase()">{{i.severity}}</span><div><b>{{i.title}}</b><small>{{i.business}} · {{i.monitor}} · {{fmt(i.opened_at)}}</small></div><span>{{i.status}}</span></div></div></el-card>
</template>
<style scoped>
.heading{display:flex;align-items:center;justify-content:space-between}.heading h2{margin:0}.heading p{margin:6px 0 0;font-size:13px;color:var(--muted)}.actions{display:flex;align-items:center;gap:10px}.live-pill{display:inline-flex;align-items:center;gap:7px;color:var(--muted);font-size:11px;padding:6px 10px;background:var(--surface);border:1px solid var(--border);border-radius:6px}.live-pill i{width:6px;height:6px;border-radius:50%;background:var(--muted)}.live-pill.online{color:var(--success);background:var(--success-soft);border-color:transparent}.live-pill.online i{background:var(--success)}.error{margin-bottom:16px}.hero-grid{display:grid;grid-template-columns:1.65fr repeat(4,minmax(0,1fr));gap:14px;margin:0 0 22px}.health-card,.metric-card{background:var(--surface);border:1px solid var(--border);border-radius:12px;min-width:0;min-height:144px;padding:20px}.health-card{display:flex;align-items:center;justify-content:space-between;gap:12px;background:var(--brand-soft);border-color:transparent;color:var(--text-primary)}.health-card span,.metric-card span{font-size:12px;color:var(--text-secondary)}.health-card strong,.metric-card strong{display:block;font-size:32px;font-weight:700;letter-spacing:-.045em;line-height:1.3;margin:10px 0 6px;font-variant-numeric:tabular-nums;color:var(--text-primary)}.health-card strong em{font-size:16px;font-style:normal;margin-left:3px}.health-card p,.metric-card p{margin:0;font-size:11px;color:var(--muted)}.metric-card.good strong{color:var(--success)}.metric-card.danger strong{color:var(--danger)}.ring{--rate:0%;width:70px;height:70px;flex:none;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--brand) var(--rate),var(--border) 0);position:relative}.ring:after{content:'';position:absolute;inset:5px;border-radius:50%;background:var(--brand-soft)}.ring b{z-index:1;font-size:11px;color:var(--brand)}.content-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:18px;margin-bottom:18px}.card-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.card-title>div{display:flex;flex-direction:column}.card-title b{font-size:14px;font-weight:650;color:var(--text-primary)}.card-title span{color:var(--muted);font-size:11px;margin-top:4px}.state-list{display:grid;gap:15px}.state-row{display:grid;grid-template-columns:96px 32px 1fr;align-items:center;gap:12px;font-size:12px;color:var(--text-secondary)}.state-row>span{display:flex;align-items:center;gap:9px}.state-row b{color:var(--text-primary);font-variant-numeric:tabular-nums}.state-row i,.state-badge i{width:7px;height:7px;border-radius:50%;background:var(--muted)}.state-row>div{height:5px;background:var(--divider);border-radius:4px;overflow:hidden}.state-row em{display:block;height:100%;background:var(--muted);border-radius:4px}.up{background-color:var(--success)!important}.down{background-color:var(--danger)!important}.degraded{background-color:var(--warning)!important}.maintenance{background-color:var(--brand)!important}.pending{background-color:var(--muted)!important}.business-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--divider)}.business-row:first-child{padding-top:0}.business-row:last-child{border-bottom:0;padding-bottom:0}.business-row>div{display:flex;flex-direction:column;min-width:0}.business-row b{font-size:13px;color:var(--text-primary);overflow-wrap:anywhere}.business-row span{font-size:11px;color:var(--muted);margin-top:4px}.business-status{padding:4px 8px;border-radius:5px;white-space:nowrap;flex:none}.business-status.up{color:var(--success);background:var(--success-soft)!important}.business-status.down{color:var(--danger);background:var(--danger-soft)!important}.business-status.degraded{color:var(--warning);background:var(--warning-soft)!important}.business-status.pending{background:var(--surface-subtle)!important;color:var(--muted)}.monitor-panel,.incident-panel{margin-bottom:18px}.state-badge{display:inline-flex;align-items:center;gap:7px;background:none!important;font-weight:550;font-size:12px}.state-badge.up{color:var(--success)}.state-badge.down{color:var(--danger)}.state-badge.degraded{color:var(--warning)}.state-badge.up i{background:var(--success)}.state-badge.down i{background:var(--danger)}.state-badge.degraded i{background:var(--warning)}.incident{display:grid;grid-template-columns:80px minmax(0,1fr) 110px;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid var(--divider)}.incident>div{display:flex;flex-direction:column}.incident small{color:var(--muted);margin-top:4px}.severity{font-size:10px;font-weight:650;text-align:center;padding:4px 8px;border-radius:5px;background:var(--surface-subtle)}.severity.critical,.severity.high{color:var(--danger);background:var(--danger-soft)}.severity.medium{color:var(--warning);background:var(--warning-soft)}
@media(max-width:1360px){.hero-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.health-card{grid-column:1/-1;min-height:116px}.health-card>div:first-child{display:grid;grid-template-columns:auto auto;align-items:center;gap:0 22px}.health-card strong{grid-row:1/3;grid-column:2;margin:0}.health-card p{margin-top:5px}.content-grid{grid-template-columns:1fr 1fr}}
@media(max-width:900px){.content-grid{grid-template-columns:1fr}.hero-grid{gap:10px}.metric-card{padding:16px;min-height:120px}.metric-card strong{font-size:26px}}
@media(max-width:600px){.hero-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.health-card{padding:16px}.health-card>div:first-child{display:block}.health-card strong{margin:6px 0}.ring{width:64px;height:64px}.incident{grid-template-columns:66px 1fr}.incident>span:last-child{grid-column:2}.actions{width:100%;flex-wrap:wrap}.live-pill{margin-right:auto}.business-status{font-size:10px}}
</style>


